File.Exists(Path.Combine(freshBundle,"registered","install-ready.json")),"Fresh target ready");foreach(string leaf in new[]{"dlpad.exe","notice.txt"})using(var a=File.OpenRead(Path.Combine(source,leaf)))using(var b=File.OpenRead(Path.Combine(freshBundle,"registered",leaf)))Require(S10FileHash(a)==S10FileHash(b),"Fresh installed source exact SHA");Require(S10FileHash(cli)==args[1]&&S10FileHash(receiptPin)==args[3],"Original CLI receipt preserved");var originals=new List<object>();foreach(var p in kept)originals.Add(new{path=p.PathName,file_id_info_hex=p.ID,sha256=p.SHA,bytes=p.Bytes});result["originals"]=originals;result["operations"]=ops;result["readonly_partial_verify_failed_unchanged"]=true;result["same_roots_prepare_refused_unchanged"]=true;result["fresh_explicit_install_reverified"]=true;result["status"]="REVIEW_REQUIRED";exit=0;}}catch(Exception error){result["error"]=error.GetType().Name+": "+error.Message;}finally{foreach(var pin in kept)pin.Dispose();if(desktop!=IntPtr.Zero){bool closed=CloseDesktop(desktop);result["private_desktop_closed"]=closed;if(!closed)exit=1;}try{string after=Input();result["input_after"]=after;bool same=result.ContainsKey("input_before")&&Object.Equals(result["input_before"],after);result["input_desktop_unchanged"]=same;if(!same)exit=1;}catch{exit=1;}if(exit!=0)result["status"]="FAIL";string json=new JavaScriptSerializer(){MaxJsonLength=1048576}.Serialize(result);if(output!=null&&Directory.Exists(output))WriteNew(Path.Combine(output,"result.json"),Encoding.UTF8.GetBytes(json));Console.WriteLine(json);}return exit;}
